package com.phira.lab;
import android.app.*;import android.content.*;import android.content.res.ColorStateList;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.os.*;import android.view.*;import android.widget.*;import java.text.DateFormat;import java.util.Date;
/** Native light dashboard. Scope selection alone never sets the connection card to active. */
public class Dashboard extends Activity {
 protected String game(){return "Phira";}protected String target(){return "org.flos.phira";}protected String expected(){return "Phira 0.8.2（39）· arm64";}
 private TextView state,stamp;private final Handler handler=new Handler(Looper.getMainLooper());
 private final Runnable refresh=new Runnable(){public void run(){refreshStatus();handler.postDelayed(this,1000);}};
 int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}
 TextView text(String value,int size,int color){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);t.setLineSpacing(dp(3),1);return t;}
 LinearLayout card(LinearLayout parent){LinearLayout c=new LinearLayout(this);c.setOrientation(1);c.setPadding(dp(20),dp(18),dp(20),dp(18));GradientDrawable bg=new GradientDrawable();bg.setColor(0xffffffff);bg.setCornerRadius(dp(18));c.setBackground(bg);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(14);parent.addView(c,lp);return c;}
 void heading(LinearLayout c,String title){TextView t=text(title,18,0xff15213a);t.setTypeface(null,Typeface.BOLD);c.addView(t);}
 void body(LinearLayout c,String value){TextView t=text(value,14,0xff526278);t.setPadding(0,dp(8),0,dp(4));c.addView(t);}
 void action(LinearLayout c,String label,boolean primary,Runnable run){Button b=new Button(this);b.setText(label);b.setTextSize(15);b.setAllCaps(false);b.setTextColor(primary?0xffffffff:0xff2458a6);b.setBackgroundTintList(ColorStateList.valueOf(primary?0xff2563eb:0xffeaf1ff));b.setMinHeight(dp(52));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(10);c.addView(b,p);b.setOnClickListener(v->run.run());}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(0xfff3f6fb);getWindow().setNavigationBarColor(0xfff3f6fb);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);
  ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(0xfff3f6fb);FrameLayout frame=new FrameLayout(this);scroll.addView(frame);LinearLayout page=new LinearLayout(this);page.setOrientation(1);page.setPadding(dp(20),dp(28),dp(20),dp(28));FrameLayout.LayoutParams pp=new FrameLayout.LayoutParams(Math.min(dp(640),getResources().getDisplayMetrics().widthPixels),-2,Gravity.TOP|Gravity.CENTER_HORIZONTAL);frame.addView(page,pp);setContentView(scroll);
  page.addView(text("本地实验 / LSPosed",13,0xff526278));TextView title=text(game(),30,0xff15213a);title.setTypeface(null,Typeface.BOLD);title.setPadding(0,dp(6),0,dp(2));page.addView(title);page.addView(text(expected(),14,0xff526278));
  LinearLayout connection=card(page);heading(connection,"连接状态");state=text("尚未诊断",19,0xff995400);state.setPadding(0,dp(12),0,dp(6));connection.addView(state);stamp=text("",12,0xff526278);connection.addView(stamp);action(connection,"启动游戏并检查连接",true,this::launch);body(connection,"首次使用先在 LSPosed 勾选目标游戏并彻底结束游戏进程。返回这里可查看本次启动报告。");
  LinearLayout play=card(page);heading(play,"游戏内控制");body(play,"音量上键打开面板，音量下键收起。自动游玩每次冷启动默认关闭；配置与本局开关分开保存。");body(play,"开发候选已连接目标分数、目标准确率、Perfect / Good 早晚与随机 / Bad / Miss 规则、按键筛选、实验历史 AP 与恢复；尚未完成真机游玩验收。自制谱与皮肤使用 Phira 原生管理；账号 RKS 不在这里改写。");
  LinearLayout network=card(page);heading(network,"保留宿主登录与联网");body(network,"模块不统一断网，也不额外阻断成绩上传。自动游玩和规则干预成绩可按原版流程尝试上传，是否接受取决于原版资格判断与服务器；不会伪造上传成功。");body(network,"独立实验档的本地恢复不会撤回已上传记录。本模块通过原版触摸输入与判定流程工作，保留用户原版模式选择及原版成绩资格判断，不保证上传被接受。");
  extraCards(page);
  LinearLayout setup=card(page);heading(setup,"设置与恢复");action(setup,"打开 LSPosed",false,()->{Intent i=getPackageManager().getLaunchIntentForPackage("org.lsposed.manager");if(i!=null)startActivity(i);else new AlertDialog.Builder(this).setTitle("选择作用域").setMessage("请从你的 LSPosed 管理器入口打开，在模块中仅勾选 "+game()+"。管理器包名可能因安装方式而不同。").setPositiveButton("知道了",null).show();});body(setup,"禁用模块后彻底结束游戏并重新打开，回到原始存档路径。不要清除或覆盖原版数据。");body(setup,"开发中 · 未真机验收。旧0.1下载已撤回，此界面不代表所有计划功能已实现。");
 }
 protected void extraCards(LinearLayout page){}
 private void launch(){try{Intent i=getPackageManager().getLaunchIntentForPackage(target());if(i==null)throw new IllegalStateException("未找到目标游戏，请核对包名与安装版本");Intent reply=new Intent(this,ConnectionReport.class);int flags=PendingIntent.FLAG_CANCEL_CURRENT|PendingIntent.FLAG_ONE_SHOT;if(Build.VERSION.SDK_INT>=31)flags|=PendingIntent.FLAG_MUTABLE;PendingIntent p=PendingIntent.getBroadcast(this,0,reply,flags);i.putExtra(ConnectionReport.EXTRA,p);getSharedPreferences("connection",0).edit().remove("state").remove("received").putLong("requested",System.currentTimeMillis()).apply();startActivity(i);}catch(RuntimeException e){new AlertDialog.Builder(this).setTitle("无法启动").setMessage(e.getMessage()).setPositiveButton("知道了",null).show();}}
 private void refreshStatus(){android.content.SharedPreferences p=getSharedPreferences("connection",0);long received=p.getLong("received",0),requested=p.getLong("requested",0);String s=p.getString("state",null);if(s!=null){state.setText(s);state.setTextColor(s.startsWith("已接入")?0xff14734b:0xff995400);stamp.setText("上次启动报告 · "+DateFormat.getDateTimeInstance().format(new Date(received))+"\n这不是持续在线检测");}else{state.setText(requested==0?"尚未诊断":System.currentTimeMillis()-requested<15000?"等待游戏报告…":"未收到启动报告");stamp.setText(requested==0?"作用域勾选不等于模块已接入":"请确认游戏已冷启动；未收到报告不能确定是框架、作用域还是游戏启动问题");}}
 @Override protected void onResume(){super.onResume();handler.post(refresh);}@Override protected void onPause(){handler.removeCallbacks(refresh);super.onPause();}
}
